import { test, expect } from '@playwright/test';

test.describe('Password Requirements Tooltip', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/password-reset');
  });

  test('should display tooltip with password requirements when password field is focused', async ({ page }) => {
    // Locate password input using getByLabel
    const passwordInput = page.getByLabel('New Password');
    await expect(passwordInput).toBeVisible();

    // Set up intercept for password validation API
    await page.route('**/api/password-validation', (route) => {
      route.abort('API call aborted');
    });

    // Focus on password input to trigger tooltip
    await passwordInput.focus();

    // Verify tooltip is visible
    const tooltip = page.getByRole('tooltip');
    await expect(tooltip).toBeVisible();

    // Verify tooltip contains required text
    await expect(tooltip).toContainText('Password must be at least 8 characters long');

    // Verify password input has required pattern attribute
    await expect(passwordInput).toHaveAttribute('pattern', '(?=.*[A-Z])(?=.*[a-z])(?=.*\\d).{8,}');

    // Verify password input has required minlength attribute
    await expect(passwordInput).toHaveAttribute('minlength', '8');

    // Verify password input has required maxlength attribute
    await expect(passwordInput).toHaveAttribute('maxlength', '256');

    // Verify password input has required placeholder
    await expect(passwordInput).toHavePlaceholder('Enter new password');

    // Verify password input has required required attribute
    await expect(passwordInput).toHaveAttribute('required', 'required');

    // Verify password input has required autocomplete attribute
    await expect(passwordInput).toHaveAttribute('autocomplete', 'new-password');

    // Verify tooltip disappears when password input loses focus
    await passwordInput.blur();
    await expect(tooltip).not.toBeVisible();
  });

  test('should not display tooltip when password field is not focused', async ({ page }) => {
    // Locate password input using getByLabel
    const passwordInput = page.getByLabel('New Password');
    await expect(passwordInput).toBeVisible();

    // Verify tooltip is not visible initially
    const tooltip = page.getByRole('tooltip');
    await expect(tooltip).not.toBeVisible();

    // Verify password input has required pattern attribute
    await expect(passwordInput).toHaveAttribute('pattern', '(?=.*[A-Z])(?=.*[a-z])(?=.*\\d).{8,}');

    // Verify password input has required minlength attribute
    await expect(passwordInput).toHaveAttribute('minlength', '8');

    // Verify password input has required maxlength attribute
    await expect(passwordInput).toHaveAttribute('maxlength', '256');

    // Verify password input has required placeholder
    await expect(passwordInput).toHavePlaceholder('Enter new password');

    // Verify password input has required required attribute
    await expect(passwordInput).toHaveAttribute('required', 'required');

    // Verify password input has required autocomplete attribute
    await expect(passwordInput).toHaveAttribute('autocomplete', 'new-password');

    // Verify tooltip does not appear when password input is not focused
    await expect(tooltip).not.toBeVisible();
  });
});
